/* This page keeps its own vocabulary and its own layout; only what the words
 * resolve to has changed, so every rule below is untouched. --card and --line
 * are absent on purpose: theme.css already owns those two names, and both
 * registers come from there now rather than from three palettes kept in step
 * by hand. */
:root{
  --paper:var(--abyss);
  --ink:var(--foam);
  --muted:var(--vapour-dim);
  --accent:var(--liquid);
  --accent-deep:var(--liquid-deep);
  --accent-soft:rgba(var(--liquid-rgb),0.13);
  --warm:var(--solid);
  --shadow:0 1px 3px rgba(var(--well-rgb),0.22);
  --font-display:var(--display);
  --font-body:var(--body);
}
/* the house bar, so this page carries the same doors as every other */
.bar{position:sticky;top:0;z-index:10;background:rgba(var(--well-rgb),0.72);backdrop-filter:blur(8px);
  border-bottom:1px solid var(--line);display:flex;align-items:center;gap:10px;padding:12px 18px;
  font-family:var(--mono);font-size:12px;letter-spacing:0.08em;color:var(--vapour-dim)}
.bar .dot{width:6px;height:6px;border-radius:50%;background:var(--liquid);box-shadow:0 0 10px var(--liquid);flex:none}
.bar b{color:var(--foam)}
.bar .spacer{flex:1}
.bar button{background:none;border:1px solid var(--line);border-radius:4px;color:var(--vapour-dim);
  font-size:12px;padding:6px 10px;cursor:pointer}
.bar button:hover{color:var(--foam);border-color:var(--line-strong)}
*{box-sizing:border-box} html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--font-body);font-size:17px;line-height:1.6;-webkit-font-smoothing:antialiased}
.wrap{max-width:40rem;margin:0 auto;padding:clamp(1.5rem,4vw,3.5rem) clamp(1.2rem,4vw,2rem)}
h1{font-family:var(--font-display);font-weight:600;font-size:clamp(2rem,5vw,3rem);line-height:1.12;letter-spacing:-.01em;margin:0;text-wrap:balance}
h2{font-family:var(--font-display);font-weight:600;font-size:1.35rem;line-height:1.25;margin:2.6rem 0 .2rem}
.eyebrow{font-size:.74rem;font-weight:650;letter-spacing:.16em;text-transform:uppercase;color:var(--accent);margin:0 0 1.1rem}
.lede{font-size:1.12rem;line-height:1.5;margin-top:1.1rem}
.note{display:flex;gap:.7rem;align-items:flex-start;margin-top:1.8rem;padding:.85rem 1.05rem;border-radius:.7rem;background:var(--accent-soft);font-size:.9rem;line-height:1.5;border:1px solid color-mix(in srgb,var(--accent) 22%,transparent)}
.note .dot{flex:none;width:.5rem;height:.5rem;margin-top:.55rem;border-radius:50%;background:var(--warm)}
.url{display:flex;gap:.6rem;align-items:center;margin:1.2rem 0 .4rem;padding:.75rem .9rem;border-radius:.6rem;background:var(--card);border:1px solid var(--line);box-shadow:var(--shadow)}
.url code{flex:1;font-family:ui-monospace,Menlo,monospace;font-size:.92rem;word-break:break-all;color:var(--ink)}
.url button{flex:none;font:inherit;font-weight:650;font-size:.82rem;color:#fff;background:var(--accent);border:none;border-radius:.45rem;padding:.4rem .75rem;cursor:pointer}
.url button:hover{background:var(--accent-deep)}
.who{font-size:.8rem;letter-spacing:.09em;text-transform:uppercase;color:var(--accent);font-weight:650;margin-top:.35rem}
ol{padding-left:1.25rem;margin:.6rem 0} ol li{margin:.42rem 0}
ul{padding-left:1.25rem;margin:.6rem 0} ul li{margin:.3rem 0}
code{font-family:ui-monospace,Menlo,monospace;font-size:.87em;background:var(--accent-soft);padding:.1rem .35rem;border-radius:.3rem}
pre{background:var(--card);border:1px solid var(--line);border-radius:.6rem;padding:.85rem 1rem;overflow-x:auto;font-size:.85rem;line-height:1.5;box-shadow:var(--shadow)}
pre code{background:none;padding:0;font-size:1em}
.muted{color:var(--muted)}
.say{margin:.7rem 0;padding:.75rem 1rem;border-left:3px solid var(--accent);background:var(--card);border-radius:0 .5rem .5rem 0;font-style:italic}
.foot{margin-top:3rem;padding-top:1.4rem;border-top:1px solid var(--line);color:var(--muted);font-size:.84rem;line-height:1.6}
.foot a{color:var(--accent-deep);font-weight:600}
a{color:var(--accent-deep)}
:focus-visible{outline:2.5px solid var(--accent);outline-offset:2px}
